/// <summary>
/// CB756_ValidationOfABNToATOSystem.
/// Batch task service class for ABN validation.
/// </summary>
class METABNValidationJobTaskService extends METSysOperationTaskService
{
    METABNValidationJobQueue abnValidationJobQueue;
    guid                     topPickingProcessId;
    AddressCountryRegionId   countryRegionId;

}

Method.Source:
    /// <summary>
    ///  Initializes the object.
    /// </summary>
    protected void initialise()
    {
        METABNValidationJobContract contract;

        super();

        // get the topPickingProcessId from the contract
        contract            = dataContract as METABNValidationJobContract;
        topPickingProcessId = contract.parmTopPickingProcessId();
        countryRegionId     = CompanyInfo::find().postalAddress().CountryRegionId;
    }

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METABNValidationJobContract</c>.
/// </param>
public void process(METABNValidationJobContract _contract)
{
    this.processInternal(_contract);
}

    /// <summary>
    /// Runs tasks of the task service class.
    /// </summary>
    /// <param name = "_readPast">Table read past setting</param>
    protected void processTask(boolean _readPast)
    {
        while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
        {
            try
            {
                if (abnValidationJobQueue.RecId != 0)
                {
                    this.execute();
                }
            }
            catch (Exception::Error)
            {
                // Catch any exception so that any one error won't bring down
                // the entire process of sales order substitution.
                Global::exceptionTextFallThrough();
            }
        }

    }

    /// <summary>
    /// Gets data to validate ABN(s) from table <c>METABNValidationJobQueue</c>.
    ///</summary>
    /// <param name = "_processId">Guid created and added in the contract <c>METABNValidationJobContract</c>.</param>
    /// <param name = "_readPast">boolean to read past records or not</param>
    /// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
    private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
    {
        #OCCRetryCount

        METABNValidationJobQueue topPickingQueue;
        int                      backOffWait;

        Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
        Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
        Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

        topPickingQueue.readPast(_readPast);

        try
        {
            ttsbegin;

            select firstonly pessimisticlock topPickingQueue
                where topPickingQueue.ProcessId == _processId;

            if (topPickingQueue.RecId)
            {
                //Copies data in abnValidationJobQueue from topPickingQueue buffer.
                abnValidationJobQueue.data(topPickingQueue);

                topPickingQueue.delete();
            }
            else
            {
                ///Empties the table buffer of abnValidationJobQueue.
                DictTable abnValidJobQueueDictTable = new DictTable(tableNum(METABNValidationJobQueue));
                abnValidationJobQueue = abnValidJobQueueDictTable.makeRecord();
            }

            ttscommit;
        }
        catch (deadLockException)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() < #RetryNum)
                {
                    backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                    sleep(xSession::currentRetryCount() * backOffWait);
                    retry;
                }
                else
                {
                    throw deadLockException;
                }
            }
            else
            {
                throw deadLockException;
            }
        }
        catch (updateConflictException)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() < #RetryNum)
                {
                    backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                    sleep(xSession::currentRetryCount() * backOffWait);
                    retry;
                }
                else
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
            }
            else
            {
                throw updateConflictException;
            }
        }
        catch (transientSqlConnectionError)
        {
            if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
            {
                retry;
            }
            else
            {
                throw transientSqlConnectionError;
            }
        }

        return (abnValidationJobQueue.RecId != 0);
    }

    /// <summary>
    /// Executes the process and logs telemetry for the ABN web service call.
    /// </summary>
    private void execute()
    {
        METATOWebServiceHelper       atoWebServiceHelper;
        System.Diagnostics.Stopwatch stopwatch;
        System.Exception             clrException;
        boolean                      callSucceeded;
        int                          infologLineBefore;
        int64                        durationMilliseconds;
        str                          failureType;
        str                          errorMessage;

        stopwatch         = System.Diagnostics.Stopwatch::StartNew();
        infologLineBefore = infolog.line();

        try
        {
            atoWebServiceHelper = METATOWebServiceHelper::construct(
                                      CustTable::find(abnValidationJobQueue.CustAccount));

            callSucceeded        = atoWebServiceHelper.callWebService(abnValidationJobQueue.ABN);
            durationMilliseconds = stopwatch.get_ElapsedMilliseconds();

            if (!callSucceeded)
            {
                // Service reachable but the call did not succeed.
                // Prefer the error captured by the helper; fall back to the infolog.
                errorMessage = atoWebServiceHelper.parmLastErrorMessage();

                if (!errorMessage)
                {
                    errorMessage = METABNValidationTelemetryHelper::infologMessages(
                                       infologLineBefore + 1, infolog.line());
                }

                METABNValidationTelemetryHelper::logFailure(
                    abnValidationJobQueue,
                    METABNValidationTelemetryHelper::failureTypeFromMessage(errorMessage),
                    errorMessage,
                    durationMilliseconds);

                return;
            }

            METABNValidationTelemetryHelper::logSuccess(abnValidationJobQueue, durationMilliseconds);

            this.updateValidationResult(atoWebServiceHelper);
        }
        catch (Exception::CLRError)
        {
            // Transport level errors that METWebService does not handle internally surface here.
            clrException = CLRInterop::getLastException();
            errorMessage = METABNValidationTelemetryHelper::clrExceptionMessage(clrException);
            failureType  = METABNValidationTelemetryHelper::failureTypeFromClrException(clrException);

            METABNValidationTelemetryHelper::logFailure(
                abnValidationJobQueue,
                failureType,
                errorMessage,
                stopwatch.get_ElapsedMilliseconds());

            // Converted to Exception::Error so processTask keeps draining the queue
            // instead of the CLR error terminating the whole batch task.
            throw error(strFmt("@MET:ABNValidationCallFailed",
                               abnValidationJobQueue.ABN,
                               abnValidationJobQueue.CustAccount,
                               errorMessage));
        }
        catch (Exception::Error)
        {
            errorMessage = METABNValidationTelemetryHelper::infologMessages(
                               infologLineBefore + 1, infolog.line());

            METABNValidationTelemetryHelper::logFailure(
                abnValidationJobQueue,
                callSucceeded ? METABNValidationFailureTypes::UpdateError
                              : METABNValidationFailureTypes::UnhandledException,
                errorMessage,
                stopwatch.get_ElapsedMilliseconds());

            throw Exception::Error;
        }
    }

    /// <summary>
    /// Applies the validation result to the referenced record.
    /// </summary>
    /// <param name = "_atoWebServiceHelper">The web service helper holding the response.</param>
    private void updateValidationResult(METATOWebServiceHelper _atoWebServiceHelper)
    {
        switch (abnValidationJobQueue.RefTableId)
        {
            case tableNum(TaxRegistration):
                _atoWebServiceHelper.updateTaxRegistration(
                    TaxRegistration::find(abnValidationJobQueue.RefRecId));
                break;

            case tableNum(TaxVATNumTable):
                _atoWebServiceHelper.updateTaxVATNumTable(
                    TaxVATNumTable::find(abnValidationJobQueue.ABN, countryRegionId));
                break;

            default:
                throw error(error::wrongUseOfFunction(funcName()));
        }
    }
